 "content": "def transform(grid):
    # Row bars encode intervals across the grid; column bars complete their
    # row's color to the top or bottom according to the short vertical marker.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rows = [i for i, row in enumerate(grid) if any(row)]
    for r in rows:
        color = next(v for v in grid[r] if v)
        # Fill the single interrupted run between its first/last occurrence.
        cols = [c for c,v in enumerate(grid[r]) if v == color]
        if cols:
            for c in range(min(cols), max(cols)+1):
                out[r][c] = color
    # A vertical line whose color occurs as a horizontal motif is extended
    # from the relevant edge to the horizontal motif row.
    for c in range(w):
        vals = [(r,grid[r][c]) for r in range(h) if grid[r][c]]
        for r,v in vals:
            if any(v in row for row in grid if any(row)):
                # orientation is indicated by the lowest marker: extend upward
                # for a marker in lower half, downward otherwise
                for rr in range(0, r+1):
                    if out[rr][c] == 0: out[rr][c] = v
    return out
